package com.figurestore.controller.admin; import com.figurestore.dto.request.UpdateOrderStatusRequest; import com.figurestore.dto.response.*; import com.figurestore.service.interfaces.OrderService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/orders") @RequiredArgsConstructor public class AdminOrderController {private final OrderService service; @GetMapping public ResponseEntity<ApiResponse<List<OrderResponse>>> all(){return ResponseEntity.ok(ApiResponse.success("Lấy danh sách đơn hàng thành công",service.all()));} @PutMapping("/{id}/status") public ResponseEntity<ApiResponse<OrderResponse>> status(@PathVariable Long id,@Valid @RequestBody UpdateOrderStatusRequest r){return ResponseEntity.ok(ApiResponse.success("Cập nhật trạng thái thành công",service.updateStatus(id,r)));}}
